        r#"<line style="stroke:{color};stroke-width:1;" x1="{}" x2="{}" y1="{}" y2="{}"/>"#,
        f(x1),
        f(x2),
        f(y1),
        f(y2),
    )

            LayoutNode::Arrow { .. } | LayoutNode::Note { .. } => {}
            _ => return false,
        }
    }
    true
}

fn swimlane_v2_arrowhead(color: &str, x: f64, y: f64) -> String {
    format!(
        r#"<polygon fill="{color}" points="{}" style="stroke:{color};stroke-width:1;"/>"#,
