let match_merge_column = |pt: (f64, f64)| -> Option<usize> {
    let mut best = None;
    let mut bestd = 6.0_f64;
    for (i, a) in nat.iter().enumerate() {
        if a.west.is_some() || pt.1 <= a.bottom {
            continue;
        }
        let d = (a.cx - pt.0).abs();
        if d < bestd {
            bestd = d;
            best = Some(i);
        }
    }
    best
};
