        c.buf,
        r#"<rect fill="none" height="{}" style="stroke:{LINE_COLOR};stroke-width:1;stroke-dasharray:5,5;" width="{}" x="{}" y="{}"/>"#,
        n(box_h),
        n(box_w),
        n(ax),
        n(ay)
    )

        c.hline_directed(h1, 0.0, posx_box, 0.5, MIN_ARROW);
        c.hline_directed(h1, posx_box + box_w, full_w, 0.5, MIN_ARROW);
    }
