let _ = write!(
    c.buf,
    r##"<text fill="#000000" font-family="sans-serif" font-size="14" lengthAdjust="spacing" textLength="{}" x="{}" y="{}">{}</text>"##,
    n(pm::text_width(trimmed, FONT_SIZE, false)),
    n(tx),
    n(ty),
    escape_xml(trimmed)
)

// PlantUML draws the raw string from x = 5, so leading whitespace offsets the
// visible glyphs; the emitted <text> carries the trimmed content with its
// textLength and an x already shifted by the leading-whitespace width.
let trimmed = raw.trim();
let leading_ws: String = raw.chars().take_while(|c| c.is_whitespace()).collect();
let lead_w = pm::text_width(&leading_ws, FONT_SIZE, false);
let baseline = 5.0 + th - pm::descent(FONT_SIZE);
let (tx, ty) = c.at(5.0 + posx_box + lead_w, baseline);
let _ = write!(
    c.buf,
    r##"<text fill="#000000" font-family="sans-serif" font-size="14" lengthAdjust="spacing" textLength="{}" x="{}" y="{}">{}</text>"##,
    n(pm::text_width(trimmed, FONT_SIZE, false)),
    n(tx),
    n(ty),
    escape_xml(trimmed)
)

    let ym = height / 2.0;
    let pts = [
        (0.0, height),
        (ctrl, height),
        (xm, ym + ctrl),
        (xm, ym),
        (xm, ym - ctrl),
        (width - ctrl, 0.0),
        (width, 0.0),
    ];
    emit_two_cubics(c, tx, ty, &pts);
}

/// Emit a path `M p0 C p1 p2 p3 C p4 p5 p6`, translated by (tx, ty).
fn emit_two_cubics(c: &mut Canvas, tx: f64, ty: f64, pts: &[(f64, f64); 7]) {
    let p: Vec<(f64, f64)> = pts.iter().map(|&(x, y)| c.at(tx + x, ty + y)).collect();
    let _ = write!(
        c.buf,
        r#"<path d="M{},{} C{},{} {},{} {},{} C{},{} {},{} {},{}" fill="none" style="stroke:{LINE_COLOR};stroke-width:1.5;"/>"#,
        n(p[0].0),
        n(p[0].1),
        n(p[1].0),
        n(p[1].1),
        n(p[2].0),
        n(p[2].1),
        n(p[3].0),
        n(p[3].1),
        n(p[4].0),
        n(p[4].1),
        n(p[5].0),
        n(p[5].1),
        n(p[6].0),
        n(p[6].1)
    )

    let ym = height / 2.0;
    let pts = [
        (0.0, height),
        (ctrl, height),
        (xm, ym + ctrl),
        (xm, ym),
        (xm, ym - ctrl),
        (width - ctrl, 0.0),
        (width, 0.0),
    ];
    emit_two_cubics(c, tx, ty, &pts);
}

