    let x1 = x - size * (angle - 0.4).cos();
    let y1 = y - size * (angle - 0.4).sin();
    let x2 = x - size * (angle + 0.4).cos();
    let y2 = y - size * (angle + 0.4).sin();
    self.line(&format!(
        r##"<polygon points="{x},{y} {x1},{y1} {x2},{y2}" fill="#000"/>"##
    )

