    r#"<path d="M{x},{y} L{x},{b} L{r},{b} L{r},{fold_y} L{fold_x},{y} L{x},{y}" fill="{NOTE_FILL}" style="stroke:{LINE_COLOR};stroke-width:0.5;"/>"#,
    x = fmt_coord(x),
    y = fmt_coord(y),
    b = fmt_coord(b),
    r = fmt_coord(r),
    fold_y = fmt_coord(fold_y),
    fold_x = fmt_coord(fold_x),
));
svg.raw(&format!(
    r#"<path d="M{fold_x},{y} L{fold_x},{fold_y} L{r},{fold_y} L{fold_x},{y}" fill="{NOTE_FILL}" style="stroke:{LINE_COLOR};stroke-width:0.5;"/>"#,
    fold_x = fmt_coord(fold_x),
    y = fmt_coord(y),
    fold_y = fmt_coord(fold_y),
    r = fmt_coord(r),
)

let (w, h) = timing_note_size(note);
let r = x + w;
let b = y + h;
let fold_x = r - NOTE_FOLD;
let fold_y = y + NOTE_FOLD;
svg.raw(&format!(
    r#"<path d="M{x},{y} L{x},{b} L{r},{b} L{r},{fold_y} L{fold_x},{y} L{x},{y}" fill="{NOTE_FILL}" style="stroke:{LINE_COLOR};stroke-width:0.5;"/>"#,
    x = fmt_coord(x),
    y = fmt_coord(y),
    b = fmt_coord(b),
    r = fmt_coord(r),
    fold_y = fmt_coord(fold_y),
    fold_x = fmt_coord(fold_x),
));
svg.raw(&format!(
    r#"<path d="M{fold_x},{y} L{fold_x},{fold_y} L{r},{fold_y} L{fold_x},{y}" fill="{NOTE_FILL}" style="stroke:{LINE_COLOR};stroke-width:0.5;"/>"#,
    fold_x = fmt_coord(fold_x),
    y = fmt_coord(y),
    fold_y = fmt_coord(fold_y),
    r = fmt_coord(r),
)

        TimelineKind::Binary | TimelineKind::Clock => constraints_h + BINARY_HEIGHT,
    }
}

fn robust_states_width(all_states: &[String]) -> f64 {
    let mut w = 0.0_f64;
    for s in all_states {
        w = w.max(text_width(s, FONT_STATE, false));
    }
    w
}

